import { observer } from "mobx-react";
import { ReactElement } from "react";
import { Deck, RatingItem } from "../../../types";
import { Grid } from "@mui/material";
import CardComponent from "../../../components/CardComponent";
import { AgCharts } from "ag-charts-react";

interface ChartViewProps {
    deck: Deck;
    display: boolean;
}

const ChartView = observer((props: ChartViewProps): ReactElement => {
    const { deck, display } = props;

    const formatratings = (ratings: RatingItem[]): { date: string; count: number }[] => {
        const format = (type: "minutes" | "hours" | "days"): [string[], { date: string; count: number }[]] => {
            let list: { date: string; count: number }[] = [];
            let textList: string[] = [];
            ratings.forEach((rating) => {
                let text = new Date(rating.date).toLocaleString();
                if (type === "minutes") {
                    text = text.slice(0, -3);
                } else if (type === "hours") {
                    text = text.slice(0, -6);
                } else if (type === "days") {
                    text = text.slice(0, -10);
                }

                textList.push(text);
                list.push({ ...rating, date: text });
            });
            return [textList, list];
        };

        const filterUnique = (texts: string[]) => {
            return texts.filter((item, index) => {
                return texts.indexOf(item) === index;
            });
        };

        let [a, b] = format("minutes");
        if (filterUnique(a).length <= 10) return b;

        [a, b] = format("hours");
        if (filterUnique(a).length <= 10) return b;

        [a, b] = format("days");
        if (filterUnique(a).length <= 10) return b;
        //@ts-ignore
        return ratings;
        // Format to minutes
    };

    return (
        <>
            {deck.cards.map((card) => {
                const options = {
                    // data: card.rating.map((rate) => ({
                    //     ...rate,
                    //     //date: new Date(rate.date).toDateString() + " " + new Date(rate.date).getHours(),
                    // })),
                    data: formatratings(card.rating),
                    series: [
                        {
                            type: "line" as "line",
                            xKey: "date",
                            yKey: "count",
                        },
                    ],
                };
                formatratings(card.rating);
                return (
                    <Grid container spacing={12} sx={{ width: "100%", display: display ? undefined : "none" }}>
                        <Grid size={6} sx={{ width: "300px", height: "420px" }}>
                            <CardComponent card={card} />
                            {/* <Box component={"img"} sx={{ width: "300px", height: "420px" }} src={card.imageUrl} /> */}
                        </Grid>
                        <Grid size={6}>
                            <AgCharts
                                options={{
                                    ...options,
                                    theme: "ag-default-dark",
                                    height: 420,
                                }}
                            />
                        </Grid>
                    </Grid>
                );
            })}
        </>
    );
});

export default ChartView;
