import { action, makeObservable, observable } from "mobx";
import { CardItem, LoadingState } from "../../types";

export default class SearchStore {
    public loadingState: LoadingState = LoadingState.notLoaded;
    public searchResults: CardItem[] = [];

    constructor() {
        makeObservable(this, {
            loadingState: observable,
            setLoadingState: action,

            searchResults: observable,
            setSearchResults: action,
        });
    }

    public setLoadingState = (newValue: LoadingState) => {
        this.loadingState = newValue;
    };

    public setSearchResults = (newValue: CardItem[]) => {
        this.searchResults = newValue;
    };
}
