export enum Sites {
    Search = "search",
    Decks = "decks",
    Rating = "rating",
    Statistics = "statistics",
}

export interface CardItem {
    imageUrl?: string;
    id: string;
    manaCost?: ManaCost;
    name: string;
    text: string;
    type: string;
    power?: string;
    toughness?: string;
    loyalty?: string;
    flavor: string;
    foreignNames?: LanguageProps[];
}
export interface RatedCardItem extends CardItem {
    rating: RatingItem[];
    id: string;
}

export interface RatingItem {
    count: number;
    date: Date;
}

interface LanguageProps {
    imageUrl?: string;
    name: string;
    text: string;
    type: string;
    flavor: string;
    language: "German" | string;
}

export enum LoadingState {
    notLoaded = "notLoaded",
    loaded = "loaded",
    loading = "loading",
    failed = "failed",
}

export type DeckType = keyof typeof DeckTypeCardCount;

export enum DeckTypeCardCount {
    "Duel" = 60,
    "Commander" = 100,
}

export interface Deck {
    name: string;
    id: string;
    deckType?: DeckType;
    cards: RatedCardItem[];
}

export type ManaString = "{G}" | "{B}" | "{U}" | "{W}" | "{R}" | `{${number}}`;
export type Mana = "G" | "B" | "U" | "W" | "R" | `${number}`;

type ManaCost = `${ManaString}`;
