/* eslint-disable react-hooks/exhaustive-deps */
import {
    Accordion,
    AccordionDetails,
    AccordionSummary,
    Box,
    Button,
    Chip,
    FormControl,
    IconButton,
    InputLabel,
    MenuItem,
    Select,
    SxProps,
    TextField,
    Typography,
} from "@mui/material";
import { observer } from "mobx-react";
import { ReactElement, useEffect, useState } from "react";
import useStores from "../../Store";
import { Add, Clear, ExpandMore } from "@mui/icons-material";
import LocalStorageController from "../LocalStorageController";
import DecksController from "./DecksController";
import CardComponent from "../../components/CardComponent";
import Neumorphism from "../../components/Neumorphism";
import { DeckType, DeckTypeCardCount } from "../../types";
import DeckTypeChip from "../../components/DeckTypeChip";
import { ScrollBarProps } from "../../Styles";

const DecksSite = observer(({ display }: { display: boolean }): ReactElement => {
    const stores = useStores();
    const { decks, setDecks } = stores.decksStore;

    const [text, setText] = useState("");
    const [deckType, setDeckType] = useState<DeckType | "ohne">("ohne");
    const availableDeckTypes: DeckType[] = ["Duel", "Commander"];

    const decksController = DecksController.getInstance(stores);
    useEffect(() => {
        const data = LocalStorageController.getInstance(stores).loadData();
        if (data) {
            setDecks(data);
        }
    }, []);
    return (
        <Box
            sx={{
                flex: 1,
                p: "1rem",
                display: display ? "flex" : "none",
                flexDirection: "column",
                minHeight: 0,
            }}
        >
            <Box
                sx={{
                    //flex: 1,
                    display: "flex",
                    justifyContent: "flex-start",
                    alignItems: "center",
                    m: "0.5rem",
                    gap: "1rem",
                }}
            >
                <Typography> Neues Deck anlegen:</Typography>
                <TextField
                    variant="filled"
                    sx={{ ...Neumorphism.TextFieldStyles }}
                    size="small"
                    value={text}
                    onChange={(e) => setText(e.target.value)}
                    label="Name"
                />
                <FormControl variant="filled" sx={{ mr: "2rem" }}>
                    <InputLabel id="select-label">Typ</InputLabel>
                    <Select
                        size="small"
                        onChange={(e) => setDeckType(e.target.value)}
                        MenuProps={{ sx: { ...Neumorphism.MenuStyles } }}
                        value={deckType}
                        labelId="select-label"
                        label="Deck auswählen"
                        sx={{
                            minWidth: "180px",
                            ...Neumorphism.SelectStyles,
                            "& .MuiSelect-select": { display: "flex", justifyContent: "center" },
                        }}
                    >
                        <MenuItem value={"ohne"}>
                            <Chip size="small" label="ohne" />
                        </MenuItem>
                        {availableDeckTypes.map((type) => {
                            return (
                                <MenuItem value={type} key={type}>
                                    <DeckTypeChip type={type} />
                                </MenuItem>
                            );
                        })}
                    </Select>
                </FormControl>
                <IconButton
                    sx={Neumorphism.ButtonStyles}
                    disabled={text.trim().length === 0}
                    onClick={() => {
                        decksController.addNewDeck(text, deckType !== "ohne" ? deckType : undefined);
                        setText("");
                        setDeckType("ohne");
                    }}
                >
                    <Add />
                </IconButton>
            </Box>
            <Typography sx={{ mb: "1rem", ml: "0.5rem" }}>Deine Decks</Typography>
            <Box
                sx={
                    {
                        ...ScrollBarProps,
                        ...Neumorphism.outsetShadow,
                        flex: 1,
                        minHeight: 0,
                        overflow: "auto",
                    } as SxProps
                }
            >
                {decks.length === 0 && <Typography fontStyle={"italic"}>Noch kein Deck angelegt</Typography>}
                {decks.map((deck) => (
                    <Accordion disableGutters key={deck.id} sx={{ background: "none" }} slotProps={{ transition: { unmountOnExit: true } }}>
                        <AccordionSummary
                            expandIcon={<ExpandMore />}
                            sx={{ "& .MuiAccordionSummary-content": { justifyContent: "space-between", alignItems: "center" } }}
                        >
                            <Box display={"flex"}>
                                <Typography sx={Neumorphism.TypographyStyles.outset}>{deck.name}</Typography>
                                {deck.deckType && <DeckTypeChip sx={{ ml: "1rem" }} type={deck.deckType} />}
                            </Box>

                            <Typography sx={{ mr: "0.5rem" }}>
                                {deck.cards.length}
                                {deck.deckType && ` / ${DeckTypeCardCount[deck.deckType]}`}
                            </Typography>
                        </AccordionSummary>
                        <AccordionDetails>
                            <>
                                {deck.cards.map((card, index) => {
                                    const germanLanguage = card.foreignNames?.find((item) => item.language === "German");

                                    const cardProps = germanLanguage ? { ...card, ...germanLanguage } : { ...card };
                                    return (
                                        <Accordion
                                            sx={{ background: "none" }}
                                            slotProps={{ transition: { unmountOnExit: true } }}
                                            disableGutters
                                            key={index}
                                        >
                                            <AccordionSummary expandIcon={<ExpandMore />}>
                                                <Typography sx={Neumorphism.TypographyStyles.outset}>{cardProps.name}</Typography>
                                            </AccordionSummary>
                                            <AccordionDetails>
                                                <CardComponent card={card} />
                                                <Button
                                                    sx={{
                                                        my: "0.5rem",
                                                        //backgroundColor: theme.palette.error.dark,
                                                        ...Neumorphism.ButtonStyles,
                                                    }}
                                                    color="error"
                                                    size="small"
                                                    // variant="contained"
                                                    onClick={() => decksController.deleteCard(deck.id, card.id)}
                                                >
                                                    <Clear />
                                                    Entfernen
                                                </Button>
                                            </AccordionDetails>
                                        </Accordion>
                                    );
                                })}
                            </>
                        </AccordionDetails>
                    </Accordion>
                ))}
            </Box>
        </Box>
    );
});

export default DecksSite;
