import {
    Button,
    Checkbox,
    Dialog,
    DialogActions,
    DialogContent,
    DialogTitle,
    List,
    ListItem,
    ListItemButton,
    ListItemIcon,
    ListItemText,
    Typography,
} from "@mui/material";
import { observer } from "mobx-react";
import { ReactElement, useState } from "react";
import { Deck } from "../types";
import useStores from "../Store";
import LocalStorageController from "../sites/LocalStorageController";

interface UploadDialogProps {
    possibleDecks: Partial<Deck[]>;
    handleClose: () => void;
}

const UploadDialog = observer((props: UploadDialogProps): ReactElement => {
    const { possibleDecks, handleClose } = props;

    const stores = useStores();
    const { setDecks } = stores.decksStore;

    const isArray = Array.isArray(possibleDecks);
    const [cardsToUpload, setCardsToUpload] = useState<number[]>(() => {
        if (isArray) {
            return possibleDecks.map((i, index) => index);
        }
        return [];
    });

    const importDecks = () => {
        const newDecks = possibleDecks.filter((d, index) => cardsToUpload.includes(index)).filter((d) => d !== undefined) as Deck[];
        LocalStorageController.getInstance(stores).saveData(newDecks);
        setDecks(newDecks);
        handleClose();
    };

    return (
        <Dialog open onClose={handleClose}>
            <DialogTitle>Decks hinzufügen</DialogTitle>
            <DialogContent>
                {!isArray && <Typography>Kein Deck gefunden</Typography>}
                {isArray && (
                    <>
                        <Typography>{possibleDecks.length} Decks gefunden:</Typography>
                        <List dense>
                            {possibleDecks.map((deck, index) => {
                                if (deck && deck.name) {
                                    return (
                                        <ListItem disableGutters key={index}>
                                            <ListItemButton
                                                onClick={() => {
                                                    if (cardsToUpload.includes(index)) {
                                                        setCardsToUpload(cardsToUpload.filter((item) => item !== index));
                                                    } else {
                                                        setCardsToUpload([...cardsToUpload, index]);
                                                    }
                                                }}
                                                dense
                                            >
                                                <ListItemIcon>
                                                    <Checkbox
                                                        edge="start"
                                                        checked={cardsToUpload.includes(index)}
                                                        //tabIndex={-1}
                                                        disableRipple
                                                    />
                                                </ListItemIcon>
                                                <ListItemText primary={`${deck!.name}: ${deck.cards.length} Karten`} />
                                            </ListItemButton>
                                        </ListItem>
                                    );
                                } else {
                                    return <Typography>Format ungültig</Typography>;
                                }
                            })}
                        </List>
                    </>
                )}
            </DialogContent>
            <DialogActions>
                <Button onClick={handleClose} variant="contained" color="error">
                    Abbrechen{" "}
                </Button>
                <Button variant="contained" onClick={importDecks} disabled={!isArray || cardsToUpload.length === 0}>
                    Importieren
                </Button>
            </DialogActions>
        </Dialog>
    );
});

export default UploadDialog;
