import { Store } from "../Store";
import { Deck } from "../types";

const LOCAL_STORAGE_KEY = "mtgRaterData";

export default class LocalStorageController {
    private static instance: LocalStorageController;
    private stores: Store;

    private constructor(stores: Store) {
        this.stores = stores;
    }

    public static getInstance = (stores: Store): LocalStorageController => {
        if (LocalStorageController.instance === undefined) {
            LocalStorageController.instance = new LocalStorageController(stores);
        }
        return LocalStorageController.instance;
    };

    public saveData = (data: Deck[]) => {
        localStorage.setItem(LOCAL_STORAGE_KEY, JSON.stringify(data));
    };

    public loadData = (): Deck[] | undefined => {
        const result = localStorage.getItem(LOCAL_STORAGE_KEY);
        if (!result) return undefined;
        const parsed = JSON.parse(result);
        if (Array.isArray(parsed)) {
            return parsed as Deck[];
        } else {
            return undefined;
        }
    };
}
