const FullTableView = observer((props: FullTableViewProps): ReactElement => {
    const { deck, display } = props;

    const getColor = (mana: Mana) => {
        switch (mana) {
            case "B":
                return "black";
            case "G":
                return "green";
            case "R":
                return "red";
            case "U":
                return "blue";
            case "W":
                return "yellow";
            default:
                return Number(mana);
        }
    };

    return (
        <Table stickyHeader sx={{ display: display ? undefined : "none" }}>
            <TableHead>
                <TableRow>
                    <TableCell>
                        <Typography>Bild</Typography>
                    </TableCell>
                    <TableCell>
                        <Typography>Name</Typography>
                    </TableCell>
                    <TableCell>
                        <Typography>Mana</Typography>
                    </TableCell>
                    <TableCell>
                        <Typography>Durchschn. Bewertung</Typography>
                    </TableCell>
                </TableRow>
            </TableHead>
            <TableBody>
                {deck.cards.map((card) => {
                    const germanLanguage = card.foreignNames?.find((item) => item.language === "German");

                    const cardProps = germanLanguage ? { ...card, ...germanLanguage } : { ...card };

                    const getAverage = () => {
                        let sum = 0;
                        card.rating.forEach((rating) => {
                            sum += rating.count;
                        });
                        return (sum / card.rating.length).toFixed(2);
                    };
                    const test = card.manaCost?.split("}{").map((item) => item.replace("{", "").replace("}", "")) as Mana[] | undefined;
                    console.log(test);
                    return (
                        <TableRow>
                            <TableCell>
                                <Image />
                            </TableCell>
                            <TableCell>
                                <Typography>{cardProps.name}</Typography>
                            </TableCell>
                            <TableCell>
                                <Box display={"flex"}>
                                    {test?.map((mana) => {
                                        const result = getColor(mana);

                                        return typeof result === "number" ? (
                                            <Typography>{result}</Typography>
                                        ) : (
                                            <Circle sx={{ color: result }} />
                                        );
                                    })}
                                </Box>
                            </TableCell>
                            <TableCell>
                                <Typography>{getAverage()}</Typography>
                            </TableCell>
                        </TableRow>
                    );
                })}
            </TableBody>
        </Table>
    );
});

export default FullTableView;
