import { AppBar, FormControl, IconButton, InputLabel, Menu, MenuItem, Select, Toolbar, Typography } from "@mui/material";
import { observer } from "mobx-react";
import { ReactElement, useRef, useState } from "react";
import useStores from "../Store";
import { Download, Menu as MenuIcon, Settings, Upload } from "@mui/icons-material";
import Neumorphism from "./Neumorphism";

const NavBar = observer((): ReactElement => {
    const stores = useStores();
    const { decks } = stores.decksStore;
    const { activeDeckId, setActiveDeckId, setMenuOpen, setPossibleDecksToUpload } = stores;

    const [settingsOpen, setSettingsOpen] = useState<boolean>(false);

    const buttonRef = useRef<HTMLButtonElement>(null);

    const download = () => {
        const a = document.createElement("a");
        const json = JSON.stringify(decks);
        const blob = new Blob([json], { type: "text/plain" });
        a.href = URL.createObjectURL(blob);
        a.download = "mtgData.mtgr";
        a.click();
    };
    const upload = () => {
        const input = document.createElement("input");
        input.type = "file";
        input.accept = ".mtgr";
        input.onchange = async (e) => {
            const fileReader = new FileReader();
            //@ts-ignore
            fileReader.readAsText(e.target.files[0], "UTF-8");
            fileReader.onload = (e) => {
                try {
                    //@ts-ignore
                    const parsed = JSON.parse(e.target.result);
                    setPossibleDecksToUpload(parsed);
                } catch (error) {
                    console.error(error);
                    stores.setAlert({ type: "error", message: "Datei konnte nicht hochgeladen werden" });
                }
            };
        };
        input.click();
    };

    return (
        <AppBar position="sticky" sx={{ backgroundColor: "rgba(18,18,18,0.6)" }}>
            <Toolbar>
                <IconButton onClick={() => setMenuOpen(true)} size="large" edge="start" color="inherit" aria-label="menu" sx={{ mr: 2 }}>
                    <MenuIcon />
                </IconButton>
                <Typography variant="h6" component="div" sx={{ flexGrow: 1 }}>
                    MTG RATER
                </Typography>

                <FormControl variant="filled" sx={{ mr: "2rem" }}>
                    <InputLabel id="select-label">Deck auswählen</InputLabel>
                    <Select
                        disabled={decks.length === 0}
                        size="small"
                        onChange={(e) => setActiveDeckId(e.target.value)}
                        MenuProps={{ sx: { ...Neumorphism.MenuStyles } }}
                        value={activeDeckId}
                        labelId="select-label"
                        label="Deck auswählen"
                        sx={{ minWidth: "180px", ...Neumorphism.SelectStyles }}
                    >
                        {decks.length === 0 && <MenuItem value=""></MenuItem>}
                        {decks.map((deck) => {
                            return (
                                <MenuItem value={deck.id} key={deck.id}>
                                    {deck.name}
                                </MenuItem>
                            );
                        })}
                    </Select>
                </FormControl>
                <IconButton ref={buttonRef} onClick={() => setSettingsOpen(!settingsOpen)} color="inherit">
                    <Settings />
                </IconButton>
                <Menu anchorEl={buttonRef.current} open={settingsOpen} onClose={() => setSettingsOpen(false)}>
                    <MenuItem onClick={download}>
                        <Download />
                        Download Data
                    </MenuItem>
                    <MenuItem onClick={upload}>
                        <Upload />
                        Upload Data
                    </MenuItem>
                </Menu>
            </Toolbar>
        </AppBar>
    );
});

export default NavBar;
