import { Box, Button, Typography } from "@mui/material";
import { observer } from "mobx-react";
import { ReactElement, useEffect, useState } from "react";
import { CardItem, DeckTypeCardCount } from "../../../types";
import { Add, Check } from "@mui/icons-material";
import DecksController from "../../decks/DecksController";
import useStores from "../../../Store";
import CardComponent from "../../../components/CardComponent";
import Neumorphism from "../../../components/Neumorphism";

interface CardDisplayProps {
    card: CardItem;
    deckId: string | undefined;
}

const CardDisplayCmp = observer((props: CardDisplayProps): ReactElement => {
    const { card, deckId } = props;

    const stores = useStores();
    const { decks } = stores.decksStore;

    const [addedToDeck, setAddedToDeck] = useState<boolean>(false);

    const decksController = DecksController.getInstance(stores);

    const activeDeck = decks.find((deck) => deck.id === deckId);
    // console.log("Deck: ", activeDeck);
    const maxCardsReached =
        activeDeck && activeDeck.deckType ? activeDeck.cards.length >= DeckTypeCardCount[activeDeck.deckType] : undefined;
    // console.log("MaxReached: ", maxCardsReached);
    const germanLanguage = card.foreignNames?.find((item) => item.language === "German");

    useEffect(() => {
        if (addedToDeck === true) {
            setTimeout(() => {
                setAddedToDeck(false);
            }, 2000);
        }
    }, [addedToDeck]);

    return (
        <Box
            sx={{
                flex: 1,
                display: "flex",
                flexDirection: "column",
                justifyContent: "flex-start",
                alignItems: "center",
                position: "relative",
            }}
        >
            <CardComponent card={card} />
            <Box
                sx={{
                    position: "absolute",
                    top: 0,
                    left: 0,
                    right: 0,
                    bottom: 0,
                    display: "flex",
                    justifyContent: "center",
                    alignItems: "center",
                    backdropFilter: "blur(4px)",
                    opacity: addedToDeck ? 1 : 0,
                    transition: "0.5s",
                    pointerEvents: "none",
                }}
            >
                <Check sx={{ fontSize: "80px" }} color="primary" />
            </Box>

            <Typography sx={{ mt: "1rem" }}>{germanLanguage ? germanLanguage.name : card.name}</Typography>
            {maxCardsReached && <Typography color="error">Maximale Kartenzahl erreicht</Typography>}

            <Button
                sx={Neumorphism.ButtonStyles}
                disabled={deckId === undefined || addedToDeck}
                color={maxCardsReached === true ? "error" : undefined}
                onClick={() => {
                    if (deckId !== undefined) {
                        setAddedToDeck(true);
                        decksController.addToDeck(card, deckId);
                    }
                }}
            >
                <Add />
            </Button>
        </Box>
    );
});

export default CardDisplayCmp;
