import { createContext, useContext } from "react";
import SearchStore from "./sites/search/SearchStore";
import DecksStore from "./sites/decks/DecksStore";
import { action, makeObservable, observable } from "mobx";
import { Deck, Sites } from "./types";
import LocalStorageController from "./sites/LocalStorageController";

interface Alert {
    type: "error" | "success" | "info";
    message: string;
}
export class Store {
    public searchStore: SearchStore = new SearchStore();
    public decksStore: DecksStore = new DecksStore();

    public activeSite: Sites = Sites.Search;
    public setActiveSite = (newSite: Sites) => {
        this.activeSite = newSite;
    };

    public activeDeckId: string = "";
    public setActiveDeckId = (newId: string) => {
        this.activeDeckId = newId;
    };

    public menuOpen: boolean = false;
    public setMenuOpen = (newValue: boolean) => {
        this.menuOpen = newValue;
    };

    public possibleDecksToUpload: Partial<Deck[]> | undefined = undefined;
    public setPossibleDecksToUpload = (newDecks: Partial<Deck[]> | undefined) => {
        this.possibleDecksToUpload = newDecks;
    };

    public alert: Alert | undefined = undefined;
    public setAlert = (newAlert: Alert | undefined) => {
        this.alert = newAlert;
    };

    constructor() {
        makeObservable(this, {
            activeSite: observable,
            setActiveSite: action,

            activeDeckId: observable,
            setActiveDeckId: action,

            menuOpen: observable,
            setMenuOpen: action,

            possibleDecksToUpload: observable,
            setPossibleDecksToUpload: action,

            alert: observable,
            setAlert: action,
        });
        const decks = LocalStorageController.getInstance(this).loadData();

        if (decks && decks.length > 0) {
            this.decksStore.setDecks(decks);
            this.setActiveDeckId(decks[0].id);
        }
    }
}

const StoreContext = createContext(new Store());
const useStores = (): Store => useContext(StoreContext);

export default useStores;
