import { Box, SxProps, Tab, Tabs } from "@mui/material";
import { observer } from "mobx-react";
import { ReactElement, useState } from "react";
import useStores from "../../Store";
import { Deck } from "../../types";
import ChartView from "./views/ChartView";
import { BarChart, FormatListBulleted, Reorder } from "@mui/icons-material";
import DetailTableView from "./views/DetailTableView";
import { ScrollBarProps } from "../../Styles";
import FullTableView from "./views/FullTableView";

const StatisticsSite = observer(({ display }: { display: boolean }): ReactElement => {
    const stores = useStores();
    const { activeDeckId } = stores;
    const { decks } = stores.decksStore;

    const activeDeck: Deck | undefined = decks.length > 0 ? decks.find((deck) => deck.id === activeDeckId) : undefined;
    const [activeTab, setActiveTab] = useState<number>(2);

    return (
        <Box sx={{ flex: 1, p: "1rem", display: display ? "flex" : "none", flexDirection: "column", minHeight: 0 }}>
            <Tabs sx={{ mb: "1rem" }} variant="fullWidth" value={activeTab} onChange={(_e, v) => setActiveTab(v)}>
                <Tab icon={<BarChart />} />
                <Tab icon={<FormatListBulleted />} />
                <Tab icon={<Reorder />} />
            </Tabs>
            <Box
                sx={
                    {
                        ...ScrollBarProps,
                        flex: 1,
                        minHeight: 0,
                        overflow: "auto",
                        // ...Neumorphism.insetShadow,
                    } as SxProps
                }
            >
                {activeDeck && <ChartView display={activeTab === 0} deck={activeDeck} />}
                {activeDeck && <DetailTableView display={activeTab === 1} deck={activeDeck} />}
                {activeDeck && <FullTableView display={activeTab === 2} deck={activeDeck} />}
            </Box>
        </Box>
    );
});

export default StatisticsSite;
