import { Box, Button as MuiButton, CircularProgress, TextField } from "@mui/material";
import { observer } from "mobx-react";
import { ReactElement, useState } from "react";
import { LoadingState } from "../../types";
import ApiController from "../../ApiController";
import useStores from "../../Store";
import CardDisplayCmp from "./components/CardDisplayCmp";
import Neumorphism from "../../components/Neumorphism";
import { ScrollBarProps } from "../../Styles";

const SearchSite = observer(({ display }: { display: boolean }): ReactElement => {
    const stores = useStores();
    const { activeDeckId } = stores;
    const { loadingState, searchResults } = stores.searchStore;

    const [text, setText] = useState("");

    const apiController = ApiController.getInstance(stores);

    return (
        <Box
            sx={{
                flex: 1,
                p: "1rem",
                display: display ? "flex" : "none",
                flexDirection: "column",
                minHeight: 0,
            }}
        >
            <Box sx={{ display: "flex", alignItems: "center", justifyContent: "space-between" }}>
                <Box
                    sx={{ display: "flex" }}
                    component={"form"}
                    autoComplete="off"
                    onSubmit={(e) => {
                        e.preventDefault();
                        apiController.search(text);
                    }}
                >
                    <TextField sx={{ ...Neumorphism.TextFieldStyles }} value={text} onChange={(e) => setText(e.target.value)}></TextField>
                    <MuiButton
                        type="submit"
                        sx={{ ...Neumorphism.ButtonStyles, ml: "1rem" }}
                        size="small"
                        onClick={(e) => {
                            e.preventDefault();
                            apiController.search(text);
                        }}
                        disabled={text.trim().length === 0}
                    >
                        Send
                    </MuiButton>
                </Box>
            </Box>
            {loadingState === LoadingState.loading && (
                <Box sx={{ display: "flex", flex: 1, justifyContent: "center", alignItems: "center" }}>
                    <Box sx={{ ...Neumorphism.insetShadow, borderRadius: "100%" }}>
                        <CircularProgress size={80} />
                    </Box>
                </Box>
            )}
            {loadingState === LoadingState.loaded && (
                <Box
                    sx={{
                        display: "flex",
                        gap: "1rem",
                        flexWrap: "wrap",
                        mt: "1rem",
                        pt: "1rem",
                        minHeight: 0,
                        overflowY: "auto",
                        ...ScrollBarProps,
                    }}
                >
                    {searchResults.map((card, index) => {
                        return <CardDisplayCmp key={index} card={card} deckId={activeDeckId} />;
                    })}
                </Box>
            )}
        </Box>
    );
});

export default SearchSite;
